//! Parameter and result schemas (CORE-CMD-002): generation from Rust types, the supported
//! subset of JSON Schema, bounded parsing of parameter text and validation with JSON-pointer
//! violations.
//!
//! Schemas are JSON Schema draft 2020-12, generated by `schemars` from the parameter and result
//! types. Validation implements the subset that generated schemas use; a schema with any other
//! keyword is rejected at registration ([`check_schema`]), so no keyword is silently ignored:
//!
//! - assertions: `type` (a name or a list of names), `enum`, `const`, `properties`,
//!   `required`, `additionalProperties` (a boolean or a schema), `items`, `prefixItems`,
//!   `minItems`, `maxItems`, `minLength`, `maxLength` (in Unicode scalar values), `minimum`,
//!   `maximum`, `exclusiveMinimum`, `exclusiveMaximum`, `oneOf`, `anyOf`, `allOf`, `$ref` to
//!   `#/$defs/<name>`, and the boolean schemas `true` and `false`;
//! - annotations, which do not affect validation: `$schema`, `$defs`, `title`, `description`,
//!   `default`, `examples`, `deprecated`, `readOnly`, `writeOnly`, `format`, `$comment` and
//!   keywords starting with `x-arc-`.
//!
//! `integer` accepts JSON numbers that are stored as integers (no fraction and no exponent);
//! numeric bounds compare as `f64`.

use arc_base::{Error, Limits, Result};
use schemars::JsonSchema;
use schemars::generate::SchemaSettings;
use serde::Serialize;
use serde_json::{Map, Value};

use crate::error::codes;

/// The most violations one validation reports; later ones are dropped.
pub const MAX_VIOLATIONS: usize = 64;

/// The most schema and instance nodes one validation visits; beyond it validation fails with
/// `cmd.params.limit_exceeded`.
pub const MAX_VALIDATION_STEPS: u64 = 1_000_000;

/// The deepest chain of nested schemas (including `$ref` hops) one validation follows.
pub const MAX_SCHEMA_DEPTH: u32 = 256;

/// The JSON Schema of `T` (draft 2020-12), with its definitions under `$defs`.
#[must_use]
pub fn schema_for<T: JsonSchema>() -> Value {
    SchemaSettings::draft2020_12()
        .into_generator()
        .into_root_schema_for::<T>()
        .to_value()
}

/// What a violation is about; serialized in `snake_case`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum ViolationKind {
    /// The value has none of the allowed types.
    Type,
    /// A required property is missing.
    Required,
    /// A property is not declared and additional properties are not allowed.
    AdditionalProperty,
    /// The value is not one of the enumerated values.
    Enum,
    /// The value is not the constant.
    Const,
    /// A number is below its minimum.
    Minimum,
    /// A number is above its maximum.
    Maximum,
    /// A text is shorter than allowed.
    MinLength,
    /// A text is longer than allowed.
    MaxLength,
    /// An array has fewer items than allowed.
    MinItems,
    /// An array has more items than allowed.
    MaxItems,
    /// No alternative of `oneOf` matches, or more than one does.
    OneOf,
    /// No alternative of `anyOf` matches.
    AnyOf,
    /// The schema at this place is `false`.
    False,
    /// The value passed the schema but cannot be read as the parameter type.
    Decode,
}

/// One schema violation: the JSON pointer (RFC 6901) of the offending value in the instance and
/// what it violates.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Serialize)]
pub struct Violation {
    /// The JSON pointer of the value; empty for the whole instance.
    pub pointer: String,
    /// The violated rule.
    pub kind: ViolationKind,
}

/// The `cmd.params.invalid` error of `violations`, with the detail `violations` as canonical JSON.
pub(crate) fn invalid(violations: &[Violation]) -> Error {
    let text = serde_json::to_string(violations).unwrap_or_default();
    Error::new(codes::PARAMS_INVALID)
        .with_arg("count", i64::try_from(violations.len()).unwrap_or(i64::MAX))
        .with_detail("violations", text)
}

/// Appends `token` to `pointer`, escaping `~` and `/`.
fn push(pointer: &str, token: &str) -> String {
    let mut out = String::with_capacity(pointer.len() + token.len() + 1);
    out.push_str(pointer);
    out.push('/');
    for c in token.chars() {
        match c {
            '~' => out.push_str("~0"),
            '/' => out.push_str("~1"),
            c => out.push(c),
        }
    }
    out
}

fn limit(reason: &'static str) -> Error {
    Error::new(codes::PARAMS_LIMIT_EXCEEDED).with_detail("limit", reason)
}

/// Parses parameter text after checking its size and nesting depth against `limits`
/// (`input_bytes`, `nesting_depth`), then checks the parsed value with [`check_limits`].
///
/// # Errors
///
/// `cmd.params.limit_exceeded` or `cmd.params.malformed`.
pub fn parse_params(text: &str, limits: &Limits) -> Result<Value> {
    if u64::try_from(text.len()).unwrap_or(u64::MAX) > limits.input_bytes {
        return Err(limit("input_bytes"));
    }
    // Nesting depth before parsing, so a deep text never reaches the parser.
    let (mut depth, mut max, mut in_string, mut escaped) = (0_u32, 0_u32, false, false);
    for byte in text.bytes() {
        if in_string {
            match (escaped, byte) {
                (true, _) => escaped = false,
                (false, b'\\') => escaped = true,
                (false, b'"') => in_string = false,
                _ => {}
            }
            continue;
        }
        match byte {
            b'"' => in_string = true,
            b'[' | b'{' => {
                depth = depth.saturating_add(1);
                max = max.max(depth);
            }
            b']' | b'}' => depth = depth.saturating_sub(1),
            _ => {}
        }
    }
    if max > limits.nesting_depth {
        return Err(limit("nesting_depth"));
    }
    let value: Value = serde_json::from_str(text).map_err(|error| {
        Error::new(codes::PARAMS_MALFORMED)
            .with_detail("line", i64::try_from(error.line()).unwrap_or(i64::MAX))
            .with_detail("column", i64::try_from(error.column()).unwrap_or(i64::MAX))
    })?;
    check_limits(&value, limits)?;
    Ok(value)
}

/// Checks a parsed value against `limits` without recursion: nesting depth, the length of each
/// text (`string_bytes`, keys included) and array (`array_length`), and the number of values
/// (`record_count`).
///
/// # Errors
///
/// `cmd.params.limit_exceeded` with the detail `limit` naming the limit.
pub fn check_limits(value: &Value, limits: &Limits) -> Result<()> {
    let too_long = |len: usize, max: u64| u64::try_from(len).unwrap_or(u64::MAX) > max;
    let mut stack = vec![(value, 1_u32)];
    let mut count = 0_u64;
    while let Some((value, depth)) = stack.pop() {
        count = count.saturating_add(1);
        if count > limits.record_count {
            return Err(limit("record_count"));
        }
        match value {
            Value::String(text) if too_long(text.len(), limits.string_bytes) => {
                return Err(limit("string_bytes"));
            }
            Value::Array(_) | Value::Object(_) if depth > limits.nesting_depth => {
                return Err(limit("nesting_depth"));
            }
            Value::Array(items) => {
                if too_long(items.len(), limits.array_length) {
                    return Err(limit("array_length"));
                }
                stack.extend(items.iter().map(|item| (item, depth + 1)));
            }
            Value::Object(map) => {
                if too_long(map.len(), limits.array_length) {
                    return Err(limit("array_length"));
                }
                for (key, item) in map {
                    if too_long(key.len(), limits.string_bytes) {
                        return Err(limit("string_bytes"));
                    }
                    stack.push((item, depth + 1));
                }
            }
            _ => {}
        }
    }
    Ok(())
}

const ANNOTATIONS: &[&str] = &[
    "$schema",
    "$defs",
    "title",
    "description",
    "default",
    "examples",
    "deprecated",
    "readOnly",
    "writeOnly",
    "format",
    "$comment",
];

const ASSERTIONS: &[&str] = &[
    "type",
    "enum",
    "const",
    "properties",
    "required",
    "additionalProperties",
    "items",
    "prefixItems",
    "minItems",
    "maxItems",
    "minLength",
    "maxLength",
    "minimum",
    "maximum",
    "exclusiveMinimum",
    "exclusiveMaximum",
    "oneOf",
    "anyOf",
    "allOf",
    "$ref",
];

const TYPES: &[&str] = &[
    "null", "boolean", "integer", "number", "string", "array", "object",
];

fn spec_error(reason: &'static str, pointer: &str) -> Error {
    Error::new(codes::SPEC_INVALID)
        .with_detail("reason", reason)
        .with_detail("schema_pointer", pointer)
}

/// Checks that `root` uses only the supported subset: known keywords, well-formed keyword
/// values, and `$ref`s that name an existing `#/$defs/<name>`.
///
/// # Errors
///
/// `cmd.spec.invalid` with the details `reason` and `schema_pointer`.
pub fn check_schema(root: &Value) -> Result<()> {
    let defs = root.get("$defs");
    let mut stack = vec![(root, String::new(), 0_u32)];
    if let Some(Value::Object(defs)) = defs {
        for (name, def) in defs {
            stack.push((def, push("/$defs", name), 1));
        }
    } else if defs.is_some() {
        return Err(spec_error("defs_not_object", "/$defs"));
    }
    while let Some((schema, at, depth)) = stack.pop() {
        if depth > MAX_SCHEMA_DEPTH {
            return Err(spec_error("too_deep", &at));
        }
        let map = match schema {
            Value::Bool(_) => continue,
            Value::Object(map) => map,
            _ => return Err(spec_error("not_a_schema", &at)),
        };
        for (key, value) in map {
            let here = push(&at, key);
            let known = ANNOTATIONS.contains(&key.as_str())
                || ASSERTIONS.contains(&key.as_str())
                || key.starts_with("x-arc-");
            if !known {
                return Err(spec_error("unsupported_keyword", &here));
            }
            if key == "$defs" && depth > 0 {
                return Err(spec_error("nested_defs", &here));
            }
            let ok = match key.as_str() {
                "type" => match value {
                    Value::String(name) => TYPES.contains(&name.as_str()),
                    Value::Array(names) => names
                        .iter()
                        .all(|n| n.as_str().is_some_and(|n| TYPES.contains(&n))),
                    _ => false,
                },
                "enum" => value.is_array(),
                "required" => value
                    .as_array()
                    .is_some_and(|names| names.iter().all(Value::is_string)),
                "minItems" | "maxItems" | "minLength" | "maxLength" => value.is_u64(),
                "minimum" | "maximum" | "exclusiveMinimum" | "exclusiveMaximum" => {
                    value.is_number()
                }
                "$ref" => value
                    .as_str()
                    .and_then(|r| r.strip_prefix("#/$defs/"))
                    .is_some_and(|name| defs.and_then(|d| d.get(name)).is_some()),
                "properties" => match value {
                    Value::Object(props) => {
                        for (name, sub) in props {
                            stack.push((sub, push(&here, name), depth + 1));
                        }
                        true
                    }
                    _ => false,
                },
                "additionalProperties" | "items" => {
                    stack.push((value, here.clone(), depth + 1));
                    true
                }
                "prefixItems" | "oneOf" | "anyOf" | "allOf" => match value {
                    Value::Array(subs) => {
                        for (i, sub) in subs.iter().enumerate() {
                            stack.push((sub, push(&here, &i.to_string()), depth + 1));
                        }
                        !subs.is_empty() || key == "prefixItems"
                    }
                    _ => false,
                },
                _ => true,
            };
            if !ok {
                return Err(spec_error("malformed_keyword", &here));
            }
        }
    }
    Ok(())
}

/// Validates `instance` against `root`, a schema [`check_schema`] accepted, and returns every
/// violation (at most [`MAX_VIOLATIONS`]) in instance order. The instance should have passed
/// [`check_limits`].
///
/// # Errors
///
/// `cmd.params.limit_exceeded` when validation needs more than [`MAX_VALIDATION_STEPS`] steps or
/// deeper schema nesting than [`MAX_SCHEMA_DEPTH`].
pub fn validate(root: &Value, instance: &Value) -> Result<Vec<Violation>> {
    let mut validator = Validator {
        defs: root.get("$defs").and_then(Value::as_object),
        steps: 0,
    };
    let mut out = Vec::new();
    validator.check(root, instance, "", 0, &mut out)?;
    out.sort();
    out.dedup();
    out.truncate(MAX_VIOLATIONS);
    Ok(out)
}

struct Validator<'s> {
    defs: Option<&'s Map<String, Value>>,
    steps: u64,
}

fn type_matches(name: &str, value: &Value) -> bool {
    match name {
        "null" => value.is_null(),
        "boolean" => value.is_boolean(),
        "integer" => value.is_i64() || value.is_u64(),
        "number" => value.is_number(),
        "string" => value.is_string(),
        "array" => value.is_array(),
        "object" => value.is_object(),
        _ => false,
    }
}

fn report(out: &mut Vec<Violation>, at: &str, kind: ViolationKind) {
    if out.len() < MAX_VIOLATIONS {
        out.push(Violation {
            pointer: at.to_owned(),
            kind,
        });
    }
}

/// The keywords that do not descend: `enum`, `const`, numeric and length bounds.
#[inline(never)]
fn check_leaf(map: &Map<String, Value>, value: &Value, at: &str, out: &mut Vec<Violation>) {
    if let Some(Value::Array(options)) = map.get("enum")
        && !options.contains(value)
    {
        report(out, at, ViolationKind::Enum);
    }
    if map.get("const").is_some_and(|constant| constant != value) {
        report(out, at, ViolationKind::Const);
    }
    let bound = |key: &str| map.get(key).and_then(Value::as_f64);
    let count = |key: &str| map.get(key).and_then(Value::as_u64);
    if let Some(number) = value.as_f64() {
        if bound("minimum").is_some_and(|b| number < b)
            || bound("exclusiveMinimum").is_some_and(|b| number <= b)
        {
            report(out, at, ViolationKind::Minimum);
        }
        if bound("maximum").is_some_and(|b| number > b)
            || bound("exclusiveMaximum").is_some_and(|b| number >= b)
        {
            report(out, at, ViolationKind::Maximum);
        }
    }
    let len = match value {
        Value::String(text) => Some((text.chars().count(), "minLength", "maxLength")),
        Value::Array(items) => Some((items.len(), "minItems", "maxItems")),
        _ => None,
    };
    if let Some((len, min, max)) = len {
        let len = u64::try_from(len).unwrap_or(u64::MAX);
        let strings = min == "minLength";
        if count(min).is_some_and(|m| len < m) {
            let kind = if strings {
                ViolationKind::MinLength
            } else {
                ViolationKind::MinItems
            };
            report(out, at, kind);
        }
        if count(max).is_some_and(|m| len > m) {
            let kind = if strings {
                ViolationKind::MaxLength
            } else {
                ViolationKind::MaxItems
            };
            report(out, at, kind);
        }
    }
}

// The validator recurses once per schema level; the parts are kept out of line so each level
// costs a small stack frame.
impl<'s> Validator<'s> {
    fn check(
        &mut self,
        schema: &'s Value,
        value: &Value,
        at: &str,
        depth: u32,
        out: &mut Vec<Violation>,
    ) -> Result<()> {
        self.steps = self.steps.saturating_add(1);
        if self.steps > MAX_VALIDATION_STEPS {
            return Err(limit("validation_steps"));
        }
        if depth > MAX_SCHEMA_DEPTH {
            return Err(limit("schema_depth"));
        }
        let map = match schema {
            Value::Bool(true) => return Ok(()),
            Value::Object(map) => map,
            _ => {
                report(out, at, ViolationKind::False);
                return Ok(());
            }
        };
        if let Some(target) = map
            .get("$ref")
            .and_then(Value::as_str)
            .and_then(|r| r.strip_prefix("#/$defs/"))
            .and_then(|name| self.defs.and_then(|d| d.get(name)))
        {
            self.check(target, value, at, depth + 1, out)?;
        }
        let type_ok = match map.get("type") {
            Some(Value::String(name)) => type_matches(name, value),
            Some(Value::Array(names)) => names
                .iter()
                .any(|n| n.as_str().is_some_and(|n| type_matches(n, value))),
            _ => true,
        };
        if !type_ok {
            // The other keywords would only repeat this violation.
            report(out, at, ViolationKind::Type);
            return Ok(());
        }
        check_leaf(map, value, at, out);
        match value {
            Value::Array(items) => self.check_items(map, items, at, depth, out)?,
            Value::Object(object) => self.check_properties(map, object, at, depth, out)?,
            _ => {}
        }
        self.check_alternatives(map, value, at, depth, out)
    }

    #[inline(never)]
    fn check_items(
        &mut self,
        map: &'s Map<String, Value>,
        items: &[Value],
        at: &str,
        depth: u32,
        out: &mut Vec<Violation>,
    ) -> Result<()> {
        let prefix = map.get("prefixItems").and_then(Value::as_array);
        let prefix_len = prefix.map_or(0, Vec::len);
        for (i, item) in items.iter().enumerate() {
            let sub = match prefix.and_then(|p| p.get(i)) {
                Some(sub) => Some(sub),
                None if i >= prefix_len => map.get("items"),
                None => None,
            };
            if let Some(sub) = sub {
                self.check(sub, item, &push(at, &i.to_string()), depth + 1, out)?;
            }
        }
        Ok(())
    }

    #[inline(never)]
    fn check_properties(
        &mut self,
        map: &'s Map<String, Value>,
        object: &Map<String, Value>,
        at: &str,
        depth: u32,
        out: &mut Vec<Violation>,
    ) -> Result<()> {
        if let Some(Value::Array(required)) = map.get("required") {
            for name in required.iter().filter_map(Value::as_str) {
                if !object.contains_key(name) {
                    report(out, &push(at, name), ViolationKind::Required);
                }
            }
        }
        let props = map.get("properties").and_then(Value::as_object);
        for (name, item) in object {
            let here = push(at, name);
            match props
                .and_then(|p| p.get(name))
                .or(map.get("additionalProperties"))
            {
                Some(Value::Bool(false)) if props.is_none_or(|p| !p.contains_key(name)) => {
                    report(out, &here, ViolationKind::AdditionalProperty);
                }
                Some(sub) => self.check(sub, item, &here, depth + 1, out)?,
                None => {}
            }
        }
        Ok(())
    }

    #[inline(never)]
    fn check_alternatives(
        &mut self,
        map: &'s Map<String, Value>,
        value: &Value,
        at: &str,
        depth: u32,
        out: &mut Vec<Violation>,
    ) -> Result<()> {
        if let Some(Value::Array(all)) = map.get("allOf") {
            for sub in all {
                self.check(sub, value, at, depth + 1, out)?;
            }
        }
        for (key, kind) in [
            ("oneOf", ViolationKind::OneOf),
            ("anyOf", ViolationKind::AnyOf),
        ] {
            if let Some(Value::Array(alternatives)) = map.get(key) {
                let mut matched = 0_usize;
                for sub in alternatives {
                    let mut scratch = Vec::new();
                    self.check(sub, value, at, depth + 1, &mut scratch)?;
                    matched += usize::from(scratch.is_empty());
                }
                let ok = if kind == ViolationKind::OneOf {
                    matched == 1
                } else {
                    matched > 0
                };
                if !ok {
                    report(out, at, kind);
                }
            }
        }
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use serde_json::json;

    use super::*;

    fn kinds(schema: &Value, value: &Value) -> Vec<(String, ViolationKind)> {
        check_schema(schema).unwrap();
        validate(schema, value)
            .unwrap()
            .into_iter()
            .map(|v| (v.pointer, v.kind))
            .collect()
    }

    #[test]
    fn each_keyword_reports_its_violation_with_a_pointer() {
        let schema = json!({
            "type": "object",
            "additionalProperties": false,
            "required": ["n", "s"],
            "properties": {
                "n": {"type": "integer", "minimum": 0, "maximum": 10},
                "x": {"type": "number", "exclusiveMinimum": 0, "exclusiveMaximum": 1},
                "s": {"type": "string", "minLength": 1, "maxLength": 3},
                "e": {"enum": ["a", "b"]},
                "c": {"const": 3},
                "a": {"type": "array", "items": {"type": "boolean"}, "minItems": 1, "maxItems": 2},
                "t": {"type": "array", "prefixItems": [{"type": "string"}, {"type": "null"}]},
                "a/b~": {"type": "null"}
            }
        });
        assert_eq!(kinds(&schema, &json!({"n": 1, "s": "ab"})), vec![]);
        let found = kinds(
            &schema,
            &json!({"n": 11, "x": 1, "e": "z", "c": 4, "a": [true, 1, false],
                    "t": [1, null], "a/b~": 0, "zz": 1}),
        );
        assert_eq!(
            found,
            vec![
                ("/a".into(), ViolationKind::MaxItems),
                ("/a/1".into(), ViolationKind::Type),
                ("/a~1b~0".into(), ViolationKind::Type),
                ("/c".into(), ViolationKind::Const),
                ("/e".into(), ViolationKind::Enum),
                ("/n".into(), ViolationKind::Maximum),
                ("/s".into(), ViolationKind::Required),
                ("/t/0".into(), ViolationKind::Type),
                ("/x".into(), ViolationKind::Maximum),
                ("/zz".into(), ViolationKind::AdditionalProperty),
            ]
        );
        assert_eq!(
            kinds(&schema, &json!({"n": -1.5, "s": ""})),
            vec![
                ("/n".into(), ViolationKind::Type),
                ("/s".into(), ViolationKind::MinLength)
            ]
        );
        assert_eq!(
            kinds(&schema, &json!([])),
            vec![(String::new(), ViolationKind::Type)]
        );
    }

    #[test]
    fn alternatives_and_references_follow_the_definitions() {
        let schema = json!({
            "$defs": {"node": {"oneOf": [
                {"type": "integer"},
                {"type": "array", "items": {"$ref": "#/$defs/node"}}
            ]}},
            "$ref": "#/$defs/node"
        });
        assert_eq!(kinds(&schema, &json!([1, [2, [3]]])), vec![]);
        assert_eq!(
            kinds(&schema, &json!([1, ["x"]])),
            vec![(String::new(), ViolationKind::OneOf)]
        );
        let any = json!({"anyOf": [{"type": "string"}, {"type": "number"}]});
        assert_eq!(
            kinds(&any, &json!(null)),
            vec![(String::new(), ViolationKind::AnyOf)]
        );
        let both = json!({"oneOf": [{"type": "number"}, {"type": "integer"}]});
        assert_eq!(
            kinds(&both, &json!(1)),
            vec![(String::new(), ViolationKind::OneOf)]
        );
        assert_eq!(
            kinds(&json!(false), &json!(1)),
            vec![(String::new(), ViolationKind::False)]
        );
    }

    #[test]
    fn unsupported_and_malformed_schemas_are_rejected() {
        for schema in [
            json!({"pattern": "a+"}),
            json!({"uniqueItems": true}),
            json!({"type": "text"}),
            json!({"$ref": "#/$defs/missing"}),
            json!({"$ref": "http://example.com/s"}),
            json!({"oneOf": []}),
            json!({"properties": {"a": {"not": {}}}}),
            json!({"minLength": -1}),
            json!(3),
        ] {
            assert_eq!(
                check_schema(&schema).unwrap_err().code(),
                "cmd.spec.invalid",
                "{schema}"
            );
        }
        check_schema(&json!({"x-arc-dimension": "length", "format": "uint8"})).unwrap();
    }

    #[test]
    fn a_reference_cycle_without_progress_is_bounded() {
        let schema = json!({"$defs": {"a": {"$ref": "#/$defs/a"}}, "$ref": "#/$defs/a"});
        check_schema(&schema).unwrap();
        assert_eq!(
            validate(&schema, &json!(1)).unwrap_err().code(),
            "cmd.params.limit_exceeded"
        );
    }

    #[test]
    fn parsing_bounds_size_depth_and_texts_before_and_after_parsing() {
        let limits = Limits {
            nesting_depth: 4,
            string_bytes: 8,
            input_bytes: 64,
            array_length: 3,
            ..Limits::DEFAULT
        };
        assert!(parse_params(r#"{"a": [[1]]}"#, &limits).is_ok());
        let code = |text: &str| parse_params(text, &limits).unwrap_err().code();
        assert_eq!(code("[[[[[1]]]]]"), "cmd.params.limit_exceeded");
        // Brackets inside strings do not count.
        assert!(parse_params(r#"["[[[[[\"x"]"#, &Limits::DEFAULT).is_ok());
        assert_eq!(code(&" ".repeat(65)), "cmd.params.limit_exceeded");
        assert_eq!(code(r#"["123456789"]"#), "cmd.params.limit_exceeded");
        assert_eq!(code("[1,2,3,4]"), "cmd.params.limit_exceeded");
        assert_eq!(code("{"), "cmd.params.malformed");
        assert_eq!(code("NaN"), "cmd.params.malformed");
        assert_eq!(code("1e999"), "cmd.params.malformed");
        let deep = "[".repeat(100_000);
        assert_eq!(
            parse_params(&deep, &Limits::DEFAULT).unwrap_err().code(),
            "cmd.params.limit_exceeded"
        );
    }
}
